CREATE TABLE IF NOT EXISTS economic_network_feedback_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, relationship_count integer NOT NULL DEFAULT 0, evidenced_relationship_count integer NOT NULL DEFAULT 0, verified_relationship_count integer NOT NULL DEFAULT 0, high_confidence_relationship_count integer NOT NULL DEFAULT 0, evidence_coverage numeric NOT NULL DEFAULT 0, verification_coverage numeric NOT NULL DEFAULT 0, confidence_coverage numeric NOT NULL DEFAULT 0, connectivity_score numeric NOT NULL DEFAULT 0, trusted_network_score numeric NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'developing', changes jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now())